<?php $title='Produk';require __DIR__.'/includes/header.php';$cat=(int)($_GET['category']??0);$cats=$pdo->query('SELECT * FROM categories ORDER BY sort_order,id DESC')->fetchAll();$sql="SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1";$params=[];if($cat){$sql.=' AND p.category_id=?';$params[]=$cat;}$sql.=' ORDER BY p.featured DESC,p.id DESC';$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();?><section class="pagehead"><small>KATALOG</small><h1>Produk Animo Label</h1><p>Pilih kategori dan temukan solusi printing yang sesuai.</p></section><section class="section"><div class="chips"><a href="/produk.php">Semua</a><?php foreach($cats as $c):?><a href="?category=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="grid products"><?php foreach($products as $p):?><article class="product"><img src="<?=e(img($p['image']))?>"><div><small><?=e($p['category_name'])?></small><h3><?=e($p['name'])?></h3><?php if($p['description']):?><p><?=e($p['description'])?></p><?php endif;if($p['price']!==''):?><strong><?=e($p['price'])?></strong><?php endif;?><a href="/produk-detail.php?id=<?=$p['id']?>">Lihat detail →</a></div></article><?php endforeach;?></div></section><?php require __DIR__.'/includes/footer.php';?>